import{_ as a,c as e,a2 as d,o as r}from"./chunks/framework.BnrAgU0Y.js";const o="/bllm/assets/7c4d9693e1207c6f257c40048849d367.E-d_41IF.png",b=JSON.parse('{"title":"Langflow 中的加载器组件","description":"Langflow 中的加载器组件","frontmatter":{"title":"Langflow 中的加载器组件","description":"Langflow 中的加载器组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-loaders.md","filePath":"langflow/components-loaders.md"}'),n={name:"langflow/components-loaders.md"};function l(i,t,s,h,u,c){return r(),e("div",null,t[0]||(t[0]=[d('<h1 id="langflow-中的加载器组件" tabindex="-1">Langflow 中的加载器组件 <a class="header-anchor" href="#langflow-中的加载器组件" aria-label="Permalink to &quot;Langflow 中的加载器组件&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>截至 Langflow 1.1，加载器组件现在可以在 <strong>组件</strong> 菜单下的 <strong>包</strong> 中找到。</p></div><p>加载器负责从各种源（如数据库、网站和本地文件）将数据导入到 Langflow 中。</p><h2 id="在流程中使用加载器组件" tabindex="-1">在流程中使用加载器组件 <a class="header-anchor" href="#在流程中使用加载器组件" aria-label="Permalink to &quot;在流程中使用加载器组件&quot;">​</a></h2><p>该流程创建了一个问答聊天机器人，用于处理加载到流程中的文档。 <a href="https://unstructured.io/" target="_blank" rel="noreferrer">Unstructured.io</a> 加载器组件从您的本地计算机加载文件，然后将其解析为结构化的 <a href="https://unstructured.io/" target="_blank" rel="noreferrer">数据</a> 对象列表。这些加载的数据用于生成 <strong>Open AI</strong> 组件对您的问题的响应。</p><p><img src="'+o+'" alt="Sample Flow retrieving data with unstructured"></p><h2 id="confluence" tabindex="-1">Confluence <a class="header-anchor" href="#confluence" aria-label="Permalink to &quot;Confluence&quot;">​</a></h2><p>Confluence 组件与 Confluence wiki 协作平台集成，用于加载和处理文档。它使用 LangChain 的 ConfluenceLoader 从指定的 Confluence 空间获取内容。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>url</td><td>站点 URL</td><td>Confluence 空间的基本 URL（例如，<code>https://company.atlassian.net/wiki</code>）</td></tr><tr><td>username</td><td>用户名</td><td>Atlassian 用户电子邮件（例如，<code>email@example.com</code>）</td></tr><tr><td>api_key</td><td>API 密钥</td><td>Atlassian API 密钥（在此创建 API 密钥：<a href="https://id.atlassian.com/manage-profile/security/api-tokens" target="_blank" rel="noreferrer">Atlassian</a>）</td></tr><tr><td>space_key</td><td>空间密钥</td><td>需要访问的 Confluence 空间的密钥</td></tr><tr><td>cloud</td><td>使用云端？</td><td>是否使用 Confluence Cloud（默认值：true）</td></tr><tr><td>content_format</td><td>内容格式</td><td>指定内容格式（默认值：STORAGE）</td></tr><tr><td>max_pages</td><td>最大页面数</td><td>要检索的最大页面数量（默认值：1000）</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>data</td><td>数据</td><td>包含加载的 Confluence 文档的数据对象列表</td></tr></tbody></table><h2 id="gitloader" tabindex="-1">GitLoader <a class="header-anchor" href="#gitloader" aria-label="Permalink to &quot;GitLoader&quot;">​</a></h2><p>GitLoader 组件使用 LangChain 的 GitLoader 从指定的 Git 仓库中获取和加载文档。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>repo_path</td><td>Repository Path</td><td>Git 仓库的本地路径</td></tr><tr><td>clone_url</td><td>Clone URL</td><td>克隆 Git 仓库的 URL（可选）</td></tr><tr><td>branch</td><td>Branch</td><td>用于加载文件的分支（默认值：&#39;main&#39;）</td></tr><tr><td>file_filter</td><td>File Filter</td><td>文件筛选模式（例如，&#39;.py&#39; 仅包括 .py 文件，&#39;!.py&#39; 排除 .py 文件）</td></tr><tr><td>content_filter</td><td>Content Filter</td><td>用于根据文件内容进行筛选的正则表达式模式</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>展示名称</th><th>信息</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>包含加载的 Git 仓库文档的 Data 对象列表</td></tr></tbody></table><h2 id="unstructured" tabindex="-1">Unstructured <a class="header-anchor" href="#unstructured" aria-label="Permalink to &quot;Unstructured&quot;">​</a></h2><p>该组件使用 <a href="https://unstructured.io/" target="_blank" rel="noreferrer">Unstructured.io</a> 无服务器 API 来加载和解析文件，将其转换为结构化的 <a href="/bllm/concepts-objects.html">数据</a> 对象列表。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>file</td><td>文件</td><td>要解析的文件路径（支持的类型列表在<a href="https://docs.unstructured.io/api-reference/api-services/overview#supported-file-types" target="_blank" rel="noreferrer">此处</a>）</td></tr><tr><td>api_key</td><td>API 密钥</td><td>Unstructured.io 无服务器 API 密钥</td></tr><tr><td>api_url</td><td>Unstructured.io API URL</td><td>Unstructured API 的可选 URL</td></tr><tr><td>chunking_strategy</td><td>分块策略</td><td>文档分块的策略（选项：&quot;&quot;, &quot;basic&quot;, &quot;by_title&quot;, &quot;by_page&quot;, &quot;by_similarity&quot;）</td></tr><tr><td>unstructured_args</td><td>附加参数</td><td>Unstructured.io API 的附加参数的可选字典</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>data</td><td>Data</td><td>包含从输入文件解析出的内容的 Data 对象列表</td></tr></tbody></table>',24)]))}const f=a(n,[["render",l]]);export{b as __pageData,f as default};
